<?php
$isTeam=$view==='team';$entries=$isTeam?$users:sql('SELECT t.*, (SELECT COUNT(*) FROM client_technicians ct JOIN clients c ON c.id=ct.clientId WHERE ct.technicianId=t.id AND c.deletedAt IS NULL) AS clients FROM technicians t WHERE t.deletedAt IS NULL ORDER BY t.nome')->fetchAll();
$edit=null;if(isset($_GET['edit'])){$id=positiveId($_GET['edit']);foreach($entries as $e)if((int)$e['id']===$id)$edit=$e;if(!$edit)throw new DomainException('Cadastro não encontrado.');}
?>
<div class="page-heading"><div><span class="eyebrow">PESSOAS QUE FAZEM ACONTECER</span><h1><?=$isTeam?'Equipe':'Contatos dos clientes'?></h1><p><?=$isTeam?'Gerencie as contas e os responsáveis pelo acompanhamento.':'Contatos dos clientes, com WhatsApp e e-mail.'?></p></div></div>
<div class="admin-layout"><section class="panel"><div class="section-heading"><h2><?=$isTeam?'Usuários':'Contatos cadastrados'?><span class="count"><?=count($entries)?></span></h2></div><div class="table-scroll"><table><thead><tr><th>Nome</th><th><?=$isTeam?'Login':'Clientes'?></th><?php if($isTeam):?><th>Acesso</th><?php else:?><th>Contato</th><?php endif;?><th>Ações</th></tr></thead><tbody><?php foreach($entries as $e):?><tr><td><span class="owner-line"><?=avatar($e['nome'],(int)$e['id'],'xs')?><strong><?=h($e['nome'])?></strong></span></td><td><?=h($isTeam?$e['login']:$e['clients'])?></td><?php if($isTeam):?><td><span class="pill neutral"><?=$e['role']==='ADMIN'?'Admin':'Equipe'?></span></td><?php else:?><td><?php technicianContacts($e);?></td><?php endif;?><td><div class="actions"><a href="?view=<?=h($view)?>&amp;edit=<?=(int)$e['id']?>" class="muted-link">Editar</a><?php if(!$isTeam):?><form method="post" data-confirm="Remover este contato? Os contatos anteriores manterão a identificação dele."><?php formAction('technician_delete',$e);?><button class="text-button text-danger">Remover</button></form><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div><?php if(!$entries):?><div class="inline-empty"><p>Nenhum contato cadastrado.</p><span>Cadastre os profissionais para começar a acompanhar os clientes.</span></div><?php endif;?></section>
<section class="panel"><h2><?=$edit?'Editar cadastro':($isTeam?'Adicionar pessoa':'Novo contato')?></h2><form method="post" class="form-stack"><?php formAction($isTeam?'user_save':'technician_save',$edit);?><label>Nome<input name="nome" required maxlength="160" value="<?=h(postVal('nome',$edit['nome']??''))?>"></label><?php if($isTeam):?><label>Login<input name="login" required minlength="3" maxlength="80" pattern="[a-zA-Z0-9._\-]{3,80}" autocomplete="off" value="<?=h(postVal('login',$edit['login']??''))?>"><small>Letras, números, ponto, hífen ou sublinhado.</small></label><label><?=$edit?'Nova senha (opcional)':'Senha inicial'?><input type="password" name="password" <?=$edit?'':'required'?> minlength="8" maxlength="72" autocomplete="new-password"><small><?=$edit?'Deixe vazio para manter a senha.':'Pelo menos 8 caracteres.'?> A pessoa definirá sua senha no próximo acesso.</small></label><label>Acesso<select name="role"><?php options(['USUARIO'=>'Equipe — gerencia clientes, contatos e tarefas','ADMIN'=>'Admin — gerencia usuários e status'],postVal('role',$edit['role']??'USUARIO'));?></select></label><?php else:?><label>WhatsApp (opcional)<input type="tel" name="whatsapp" maxlength="40" placeholder="(11) 99999-9999" value="<?=h(postVal('whatsapp',$edit['whatsapp']??''))?>"><small>DDD e número para Brasil; + e código do país para outros países.</small></label><label>E-mail (opcional)<input type="email" name="email" maxlength="254" value="<?=h(postVal('email',$edit['email']??''))?>"></label><label>Vincular a um cliente (opcional)<select name="linkClientId"><option value="">Não adicionar vínculo agora</option><?php foreach(sql('SELECT id,nome FROM clients WHERE deletedAt IS NULL ORDER BY nome')->fetchAll() as $linkClient):?><option value="<?=(int)$linkClient['id']?>" <?=postVal('linkClientId')===(string)$linkClient['id']?'selected':''?>>#<?=(int)$linkClient['id']?> · <?=h($linkClient['nome'])?></option><?php endforeach;?></select><small>Adiciona o vínculo ao salvar. Os vínculos existentes são preservados.</small></label><?php endif;?><button class="button primary">Salvar <?=$isTeam?'pessoa':'contato'?></button><?php if($edit):?><a class="muted-link" href="?view=<?=h($view)?>">Cancelar edição</a><?php endif;?></form></section></div>
